eyPacketSignature: sessionKeySignature };\n};\n\nexport const generateDriveBootstrap = async (addressPrivateKey: PrivateKeyReference) => {\n    const {\n        NodeKey: ShareKey,\n        NodePassphrase: SharePassphrase,\n        privateKey: sharePrivateKey,\n        NodePassphraseSignature: SharePassphraseSignature,\n    } = await generateNodeKeys(addressPrivateKey);\n\n    const {\n        NodeKey: FolderKey,\n        NodePassphrase: FolderPassphrase,\n        privateKey: folderPrivateKey,\n        NodePassphraseSignature: FolderPassphraseSignature,\n    } = await generateNodeKeys(sharePrivateKey, addressPrivateKey);\n\n    const FolderName = await encryptName('root', sharePrivateKey, addressPrivateKey);\n\n    return {\n        bootstrap: {\n            SharePassphrase,\n            SharePassphraseSignature,\n            FolderPassphrase,\n            FolderPassphraseSignature,\n            ShareKey,\n            FolderKey,\n            FolderName,\n        },\n        sharePrivateKey,\n        folderPrivateKey,\n    };\n};\n","export const HTTP_ERROR_CODES = {\n    ABORTED: -1,\n    TIMEOUT: 0,\n    UNPROCESSABLE_ENTITY: 422,\n    UNAUTHORIZED: 401,\n    UNLOCK: 403,\n    TOO_MANY_REQUESTS: 429,\n    BAD_GATEWAY: 502,\n    SERVICE_UNAVAILABLE: 503,\n    GATEWAY_TIMEOUT: 504,\n};\n\nexport const API_CUSTOM_ERROR_CODES = {\n    APP_VERSION_BAD: 5003,\n    ALREADY_USED: 2001,\n    USERNAME_ALREADY_USED: 12106,\n    EMAIL_FORMAT: 2050,\n    INVALID_DOMAIN_NAME: 2059,\n    INVALID_URL: 2052,\n    NOT_ALLOWED: 2011,\n    CARD_DECLINED: 2902,\n    AUTH_SWITCH_TO_SSO: 8100,\n    AUTH_SWITCH_TO_SRP: 8101,\n    HUMAN_VERIFICATION_REQUIRED: 9001,\n    DEVICE_VERIFICATION_REQUIRED: 9002,\n    INBOX_DESKTOP_TRIAL_END: 9200,\n    AUTH_ACCOUNT_DISABLED: 10003,\n    USER_UPDATE_EMAIL_SELF: 12007,\n    TOKEN_INVALID: 12087,\n    KEY_GET_INPUT_INVALID: 33101,\n    KEY_GET_ADDRESS_MISSING: 33102,\n    KEY_GET_DOMAIN_EXTERNAL: 33103,\n    KEY_GET_INVALID_KT: 33104,\n    INCOMING_D