 give a response. It can return these codes when acting as a proxy (e.g. email-list unsubscribe).\n    return (\n        [HTTP_ERROR_CODES.BAD_GATEWAY, HTTP_ERROR_CODES.GATEWAY_TIMEOUT].includes(e.status) &&\n        e.data?.Code === undefined\n    );\n};\n\nexport const getIsNetworkError = (e: any) => {\n    if (!e) {\n        return false;\n    }\n    return e.name === 'NetworkError' || e.message?.toLowerCase() === 'network error';\n};\n\nexport const getIsTimeoutError = (e: any) => {\n    if (!e) {\n        return false;\n    }\n    return e.name === 'TimeoutError';\n};\n\nexport const getIsConnectionIssue = (e: any) => {\n    return getIsOfflineError(e) || getIsUnreachableError(e) || getIsNetworkError(e) || getIsTimeoutError(e);\n};\n\nexport const getApiErrorMessage = (e: any): string | undefined => {\n    const { message } = getApiError(e);\n    if (getIs401Error(e)) {\n        return message || c('Info').t`Session timed out`;\n    }\n    if (getIsOfflineError(e)) {\n        return message || c('Info').t`Internet connection lost`;\n    }\n    if (getIsUnreachableError(e)) {\n        return message || c('Info').t`Servers are unreachable. Please try again in a few minutes`;\n    }\n    if (getIsTimeoutError(e)) {\n        return message || c('Error').t`Request timed out`;\n    }\n    if (message) {\n        return `${message}`;\n    }\n};\n","import type { CaptureContext } from '@sentry/types';\n\nimport { SafeErrorObject } from '@proton/utils/getSafeErrorObject';\n\nexport const isEnrichedError = (err: unknown): err is EnrichedError => {\n    return (\n        err instanceof EnrichedError ||\n        (!!err &&\n            typeof err === 'object' &&\n            'name' in err &&\n            typeof err.name === 'string' &&\n            'message' in err &&\n            typeof err.message === 'string' &&\n            'isEnrichedError' in err &&\n            err.isEnrichedError === true)\n    );\n};\n\n/**\n * This error is used when wanting to pass extra information to Sentry.\n *\n * JavaScript errors offer the `cause` property to provide extra information,\n * however there is a `core-js` bug in the version we use which can cause\n * crashes when the Error object gets cloned. Hence, this custom error.\n *\n * We can use these properties from Sentry's `CaptureContext`:\n * - `tags`, which are searchable, and must be primitives\n * - `extra`, which can be structured data\n */\nexport class EnrichedError extends Error {\n    isEnrichedError: boolean = true;\n\n    context?: CaptureContext;\n\n    /**\n     * An optional message to be used for Sentry instead of the `message` property.\n     *\n     * Useful in case of localized messages, to pass the original message.\n     */\n    sentryMessage?: string;\n\n    constructor(message: string, context?: CaptureContext, sentryMessage?: string) {\n        super(message);\n\n        // It is important that the name is \"Error\", as we want it\n        // to be compatible with existing handlers, and mitigate\n        // the chances of the actual name showing in the UI\n        this.name = 'Error';\n\n        this.context = context;\n        this.sentryMessage = sentryMessage;\n    }\n}\n\n/**\n * Converts a `SafeErrorObject` to the appropriate `Error` or `EnrichedError`.\n */\nexport const convertSafeError = (obj: SafeErrorObject) => {\n    let error;\n\n    if (isEnrichedError(obj)) {\n        error = new EnrichedError(obj.message, obj.context);\n    } else {\n        error = new Error(obj.message);\n    }\n    error.name = obj.name;\n    error.stack = obj.stack;\n\n    // Sentry message may be present on other error types\n    if (obj.sentryMessage) {\n        (error as any).sentryMessage = obj.sentryMessage;\n    }\n\n    return error;\n};\n","export function isValidationError(err: any): err is ValidationError {\n    return err.name === 'ValidationError';\n}\n\nexport class ValidationError extends Error {\n    constructor(message: string) {\n        super(message);\n        this.name = 'ValidationError';\n    }\n}\n","import bcrypt from 'bcryptjs';\n\nimport { CryptoProxy } from '@proton/crypto';\nimport {\n    arrayToBinaryString,\n    arrayToHexString,\n    binaryStringToArray,\n    encodeBase64,\n    encodeUtf8,\n} from '@proton/crypto/lib/utils';\nimport mergeUint8Arrays from '@proton/utils/mergeUint8Arrays';\n\nimport { BCRYPT_PREFIX } from './constants';\nimport { cleanUsername } from './utils/username';\n\n/**\n * Expand a hash\n */\nexport const expandHash = async (input: Uint8Array) => {\n    const promises = [];\n    const arr = mergeUint8Arrays([input, new Uint8Array([0])]);\n    for (let i = 1; i <= 4; i++) {\n        promises.push(CryptoProxy.computeHash({ algorithm: 'SHA512', data: arr }));\n        arr[arr.length - 1] = i;\n    }\n    return mergeUint8Arrays(await Promise.all(promises));\n};\n\n/**\n * Format a hash\n */\nconst formatHash = async (password: string, salt: string, modulus: Uint8Array) => {\n    const unexpandedHash = await bcrypt.hash(password, BCRYPT_PREFIX + salt);\n    return expandHash(mergeUint8Arrays([binaryStringToArray(unexpandedHash), modulus]));\n};\n\n/**\n * Hash password in version 3.\n */\nconst hashPassword3 = (password: string, salt: string, modulus: Uint8Array) => {\n    const saltBinary = binaryStringToArray(`${salt}proton`);\n    return formatHash(password, bcrypt.encodeBase64(saltBinary, 16), modulus);\n};\n\n/**\n * Hash password in version 1.\n */\nconst hashPassword1 = async (password: string, username: string, modulus: Uint8Array) => {\n    const value = binaryStringToArray(encodeUtf8(username.toLowerCase()));\n    const salt = arrayToHexString(await CryptoProxy.computeHash({ algorithm: 'unsafeMD5', data: value }));\n    return formatHash(password, salt, modulus);\n};\n\n/**\n * Hash password in version 0.\n */\nconst hashPassword0 = async (password: string, username: string, modulus: Uint8Array) => {\n    const value = await CryptoProxy.computeHash({\n        algorithm: 'SHA512',\n      