izes}\" is not valid`);\n        return undefined;\n    }\n    if (!blockSizes.every((item) => typeof item === 'number')) {\n        console.warn(`XAttr block sizes \"${blockSizes}\" is not valid`);\n        return undefined;\n    }\n    return blockSizes as number[];\n}\n\nfunction parseMedia(xattr: MaybeExtendedAttributes): { Width: number; Height: number; Duration?: number } | undefined {\n    const media = xattr?.Media;\n    if (media === undefined || media.Width === undefined || media.Height === undefined) {\n        return undefined;\n    }\n    const width = media.Width;\n    if (typeof width !== 'number') {\n        console.warn(`XAttr media width \"${width}\" is not valid`);\n        return undefined;\n    }\n    const height = media.Height;\n    if (typeof height !== 'number') {\n        console.warn(`XAttr media height \"${height}\" is not valid`);\n        return undefined;\n    }\n    const duration = media.Duration;\n    if (duration !== undefined && typeof duration !== 'number') {\n        console.warn(`XAttr media duration \"${duration}\" is not valid`);\n        return undefined;\n    }\n    return {\n        Width: width,\n        Height: height,\n        Duration: duration,\n    };\n}\n\nfunction parseDigests(xattr: MaybeExtendedAttributes): { SHA1: string } | undefined {\n    const digests = xattr?.Common?.Digests;\n    if (digests === undefined || digests.SHA1 === undefined) {\n        return undefined;\n    }\n\n    const sha1 = digests.SHA1;\n    if (typeof sha1 !== 'string') {\n        console.warn(`XAttr digest SHA1 \"${sha1}\" is not valid`);\n        return undefined;\n    }\n\n    return {\n        SHA1: sha1,\n    };\n}\n\nfunction dateToIsoString(date: Date) {\n    const isDateValid = !Number.isNaN(date.getTime());\n    return isDateValid ? date.toISOString() : undefined;\n}\n","import { c, msgid } from 'ttag';\n\nimport { SORT_DIRECTION } from '@proton/shared/lib/constants';\nimport { RESPONSE_CODE } from '@proton/shared/lib/drive/constants';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { sendErrorReport } from '../../../utils/errorHandling';\nimport { useErrorHandler, waitFor } from '../../_utils';\nimport { DecryptedLink, EncryptedLink } from '../interface';\nimport useLinks from '../useLinks';\nimport useLinksState, { Link, isLinkDecrypted } from '../useLinksState';\n\nexport type FetchMeta = {\n    isEverythingFetched?: boolean;\n    isInProgress?: boolean;\n    lastSorting?: SortParams;\n    lastPage?: number;\n};\n\n/**\n * Available sorting methods for listing.\n */\nexport type SortParams = {\n    sortField: 'size' | 'createTime' | 'metaDataModifyTime';\n    sortOrder: SORT_DIRECTION;\n};\n\n/**\n * FetchResponse is internal data holder of results from API.\n */\nexport type FetchResponse = {\n    // links contain all requests links (that is links in specified folder\n    // in case folder children were requested).\n    links: EncryptedLink[];\n    // parents contain links not directly requested but needed so they can\n    // be decrypted (useful for shared links which don't have the same\n    // parent, for example).\n    parents: EncryptedLink[];\n};\n\n// API supports up to 150 but we hardly fit 150 items on the page anyway.\n// Because decrypting takes time, lets do it in smaller batches. We could\n// optimise it to do it in smaller batches for listings when we can use\n// sorting on API, but the maximum what API allows for cases when we need\n// to load everything anyway. That is a bit tricky, as it needs more complex\n// paging algorithm (to properly compute page when page size differs).\n// Therefore, lets keep it simple for now unless it is really needed.\nexport const PAGE_SIZE = 50;\nexport const DEFAULT_SORTING: SortParams = {\n    sortField: 'createTime',\n    sortOrder: SORT_DIRECTION.ASC,\n};\n\n/**\n * Provides helpers to list links.\n */\nexport function useLinksListingHelpers() {\n    const { showErrorNotification, showAggregatedErrorNotification } = useErrorHandler();\n    const linksState = useLinksState();\n    const { decryptLinks } = useLinks();\n\n    /**\n     * Decrypts links in parallel and caches them.\n     */\n    const decryptAndCacheLinks = async (abortSignal: AbortSignal, shareId: string, links: EncryptedLink[]) => {\n        if (!links.length) {\n            return {\n                links: [],\n                errors: [],\n            };\n        }\n\n        const result = await decryptLinks(abortSignal, shareId, links);\n\n        if (result.links.length) {\n            linksState.setLinks(shareId, result.links);\n        }\n\n        if (result.errors.length) {\n            showAggregatedErrorNotification(result.errors, (errors: any[]) => {\n                const count = errors.length;\n                return c('Notification').ngettext(\n                    msgid`${count} item failed to be decrypted`,\n                    `${count} items failed to be decrypted`,\n                    count\n                );\n            });\n        }\n\n        return result;\n    };\n\n    /**\n     * Caches encrypted links and decrypts them.\n     */\n    const cacheLoadedLinks = async (\n        abortSignal: AbortSignal,\n        shareId: string,\n        links: EncryptedLink[],\n        parents: EncryptedLink[]\n    ) => {\n        // Set encrypted data right away because it is needed for decryption\n        const allEncryptedLinks = [...parents, ...links].map((encrypted) => ({ encrypted }));\n        linksState.setLinks(shareId, allEncryptedLinks);\n\n        // Decrypt only links which are not decrypted yet or need re-decryption\n        const decryptedLinks: Required<Link>[] = [];\n        const encryptedLinks: EncryptedLink[] = [];\n\n        links.forEach((link) => {\n            const cachedLink = linksState.getLink(shareId, link.linkId);\n\n            if (isLinkDecrypted(cachedLink)) {\n                decryptedLinks.push(cachedLink);\n            } else {\n                encryptedLinks.push(link);\n            }\n        });\n\n        // Merge results to return all provided links\n        const result = await decryptAndCacheLinks(abortSignal, shareId, encryptedLinks);\n\n        return {\n            links: [...decryptedLinks, ...result.links],\n            errors: result.errors,\n        };\n    };\n\n    /**\n     * Ensures only one fetch for the given\n     * `fetchMeta` is in progress, and it never runs if all was already fetched\n     * before.\n     * The algorithm also ensures proper paging; e.g., if first page used sort\n     * by create time, and next page uses the same sorting, paging can continue,\n     * but if the sort is different, we need to start from page one again, so\n     * we don't miss any link.\n     * In case no sorting is provided, the previously used one is used; that is\n     * useful for example when some pages were already loaded and then we just\n     * don't care about sorting but we want to load everything.\n     * The return value is boolean whether there is next page.\n     */\n    const fetchNextPageWithSortingHelper = async (\n        abortSignal: AbortSignal,\n        shareId: string,\n        sorting: SortParams | undefined,\n        fetchMeta: FetchMeta,\n        fetchLinks: (sorting: SortParams, page: number) => Promise<FetchResponse>,\n        showNotification = true\n    ): Promise<boolean> => {\n        await waitFor(() => !fetchMeta.isInProgress, { abortSignal });\n        if (fetchMeta.isEverythingFetched) {\n            return false;\n        }\n        fetchMeta.isInProgress = true;\n        const currentSorting = sorting || fetchMeta.lastSorting || DEFAULT_SORTING;\n        const currentPage =\n            isSameSorting(fetchMeta.lastSorting, currentSorting) && fetchMeta.lastPage !== undefined\n                ? fetchMeta.lastPage + 1\n                : 0;\n        const hasNextPage = await fetchLinks(currentSorting, currentPage)\n            .then(async ({ links, parents }) => {\n                fetchMeta.lastSorting = currentSorting;\n                fetchMeta.lastPage = currentPage;\n                fetchMeta.isEverythingFetched = links.length < PAGE_SIZE;\n\n                await cacheLoadedLinks(abortSignal, shareId, links, parents);\n\n                return !fetchMeta.isEverythingFetched;\n            })\n            .catch((err) => {\n                if (err?.data?.Code === RESPONSE_CODE.INVALID_LINK_TYPE) {\n                    throw err;\n                }\n                // If you do bigger changes around, consider this:\n                // It looked like a good idea to handle errors by showing\n                // notification here to handle all places nicely on one\n                // place without need to duplicate the code. However, for\n                // download, we need to throw exception back so it can be\n                // properly handled by transfer manager. But still, for all\n                // other places its convenient to handle here. Maybe in the\n                // future we could do another helper which would wrap the\n                // logic with notifications, similarly like we have hook\n                // useActions, to have better freedom to chose what to use.\n                if (showNotification) {\n                    showErrorNotification(err, c('Notification').t`Cannot load next page`);\n                    // Very probably the next page is still there, but to not cause\n                    // inifinite loop requesting next page, lets return false.\n                    return false;\n                }\n                throw err;\n            })\n            .finally(() => {\n                // Make sure isInProgress is always unset, even during failure,\n                // and that it is the last thing after everything else is set.\n                fetchMeta.isInProgress = false;\n            });\n\n        return hasNextPage;\n    };\n\n    /**\n     * A wrapper around fetchNextPageWithSortingHelper.\n     * Basically the same thing, just for cases when sorting is not available\n     * (for example, listing trash or shared links).\n     */\n    const fetchNextPageHelper = async (\n        abortSignal: AbortSignal,\n        shareId: string,\n        fetchMeta: FetchMeta,\n        fetchLinks: (page: number) => Promise<FetchResponse>\n    ): Promise<boolean> => {\n        return fetchNextPageWithSortingHelper(abortSignal, shareId, undefined, fetchMeta, (_, page: number) =>\n            fetchLinks(page)\n        );\n    };\n\n    /**\n     * Invokes a callback function until all pages are loaded. The callback function must\n     * return a boolean value representing a presence of the next page in listing.\n     */\n    const loadFullListing = async (callback: () => Promise<boolean>): Promise<void> => {\n        const hasNextPage = await callback();\n\n        if (hasNextPage) {\n            await loadFullListing(callback);\n        }\n    };\n\n    /**\n     * Invokes a callback function until all pages are loaded using technique with AnchorID.\n     * The callback function must return a AnchorID and More as boolean value representing a presence of the next page in listing.\n     */\n    const loadFullListingWithAnchor = async (\n        callback: (AnchorID?: string) => Promise<{ AnchorID: string; More: boolean }>,\n        AnchorIdIn?: string\n    ): Promise<void> => {\n        const result = await callback(AnchorIdIn);\n\n        if (result.More) {\n            await loadFullListingWithAnchor(callback, result.AnchorID);\n        }\n    };\n\n    /**\n     * Returns cached decrypted links (including stale), decrypts\n     * all encrypted or stale links in the background.\n     */\n    const getDecryptedLinksAndDecryptRest = (\n        abortSignal: AbortSignal,\n        shareId: string,\n        links: Link[],\n        fetchMeta?: FetchMeta\n    ): { links: DecryptedLink[]; isDecrypting: boolean } => {\n        // Return decrypted links right away.\n        // Those links the have been updated in the background by an event,\n        // still need to be decrypted. We run descryption asynchronous.\n        const linksToBeDecrypted = links\n            .filter(\n                ({ decrypted }) =>\n                    decrypted?.isStale ||\n                    // Link was added outside of this listing and thus we need to decrypt it now\n                    // (if the listing is in progress, it might still be decrypted)\n                    (!decrypted && !fetchMeta?.isInProgress) // Link was added not by listing.\n            )\n            .map(({ encrypted }) => encrypted);\n        decryptAndCacheLinks(abortSignal, shareId, linksToBeDecrypted).catch(sendErrorReport);\n\n        return {\n            links: links.map(({ decrypted }) => decrypted).filter(isTruthy),\n            isDecrypting: linksToBeDecrypted.length > 0,\n        };\n    };\n\n    return {\n        cacheLoadedLinks,\n        fetchNextPageWithSortingHelper,\n        fetchNextPageHelper,\n        loadFullListing,\n        loadFullListingWithAnchor,\n        getDecryptedLinksAndDecryptRest,\n    };\n}\n\nfunction isSameSorting(one?: SortParams, other?: SortParams): boolean {\n    return (\n        one !== undefined &&\n        other !== undefined &&\n        one.sortField === other.sortField &&\n        one.sortOrder === other.sortOrder\n    );\n}\n\nexport function sortParamsToServerSortArgs({ sortField, sortOrder }: SortParams): { Sort: string; Desc: 0 | 1 } {\n    const Sort = {\n        mimeType: 'MIMEType',\n        size: 'Size',\n        createTime: 'CreateTime',\n        metaDataModifyTime: 'ModifyTime',\n    }[sortField];\n    return {\n        Sort,\n        Desc: sortOrder === SORT_DIRECTION.ASC ? 0 : 1,\n    };\n}\n","import { c, msgid } from 'ttag';\n\nimport { MAX_NAME_LENGTH } from '@proton/shared/lib/drive/constants';\n\nconst composeValidators =\n    <T>(validators: ((value: T) => string | undefined)[]) =>\n    (value: T) => {\n        for (const validator of validators) {\n            const result = validator(value);\n            if (result) {\n                return result;\n            }\n        }\n        return undefined;\n    };\n\nconst validateNameLength = (str: string) => {\n    return str.length > MAX_NAME_LENGTH\n        ? c('Validation Error').ngettext(\n              msgid`Name must be ${MAX_NAME_LENGTH} character long at most`,\n              `Name must be ${MAX_NAME_LENGTH} characters long at most`,\n              MAX_NAME_LENGTH\n          )\n        : undefined;\n};\n\nconst validateNameEmpty = (str: string) => {\n    return !str ? c('Validation Error').t`Name must not be empty` : undefined;\n};\n\nexport const validateLinkName = composeValidators([validateNameEmpty, validateNameLength]);\n\nexport const validateLinkNameField = composeValidators([validateNameEmpty, validateNameLength]);\n","import { usePreventLeave } from '@proton/components';\nimport { CryptoProxy } from '@proton/crypto';\nimport {\n    queryDeleteChildrenLinks,\n    queryDeleteTrashedLinks,\n    queryEmptyTrashOfShare,\n    queryRestoreLinks,\n    queryTrashLinks,\n} from '@proton/shared/lib/api/drive/link';\nimport { queryMoveLink } from '@proton/shared/lib/api/drive/share';\nimport { queryVolumeEmptyTrash } from '@proton/shared/lib/api/drive/volume';\nimport { BATCH_REQUEST_SIZE, MAX_THREADS_PER_REQUEST, RESPONSE_CODE } from '@proton/shared/lib/drive/constants';\nimport runInQueue from '@proton/shared/lib/helpers/runInQueue';\nimport { encryptPassphrase, generateLookupHash } from '@proton/shared/lib/keys/driveKeys';\nimport { getDecryptedSessionKey } from '@proton/shared/lib/keys/drivePassphrase';\nimport chunk from '@proton/utils/chunk';\nimport groupWith from '@proton/utils/groupWith';\n\nimport { EnrichedError } from '../../utils/errorHandling/EnrichedError';\nimport { ValidationError } from '../../utils/errorHandling/ValidationError';\nimport { useDebouncedRequest } from '../_api';\nimport { useDriveEventManager } from '../_events';\nimport { useDefaultShare, useShare } from '../_shares';\nimport { useVolumesState } from '../_volumes';\nimport useLink from './useLink';\nimport useLinks from './useLinks';\nimport useLinksState from './useLinksState';\n\nconst INVALID_REQUEST_ERROR_CODES = [RESPONSE_CODE.ALREADY_EXISTS, RESPONSE_CODE.INVALID_REQUIREMENT];\n\ninterface APIResponses {\n    Responses: {\n        Response: {\n            Code: RESPONSE_CODE;\n            Error?: string;\n        };\n    }[];\n}\n\n/**\n * useLinksActions provides actions for manipulating with links in batches.\n */\nexport function useLinksActions({\n    queries,\n}: {\n    queries: {\n        queryDeleteChildrenLinks: typeof queryDeleteChildrenLinks;\n        queryDeleteTrashedLinks: typeof queryDeleteTrashedLinks;\n        queryEmptyTrashOfShare: typeof queryEmptyTrashOfShare;\n        queryRestoreLinks: typeof queryRestoreLinks;\n        queryTrashLinks: typeof queryTrashLinks;\n    };\n}) {\n    const { preventLeave } = usePreventLeave();\n    const debouncedRequest = useDebouncedRequest();\n    const events = useDriveEventManager();\n    const { getLink, getLinkPassphraseAndSessionKey, getLinkPrivateKey, getLinkHashKey } = useLink();\n    const { getLinks } = useLinks();\n    const { lockLinks, lockTrash, unlockLinks } = useLinksState();\n    const { getDefaultShare } = useDefaultShare();\n\n    const { getShareCreatorKeys } = useShare();\n    const volumeState = useVolumesState();\n\n    /**\n     * withLinkLock is helper to lock provided `linkIds` before the action done\n     * using `callback`, and ensure links are unlocked after its done no matter\n     * the result of the action.\n     */\n    const withLinkLock = async <T>(shareId: string, linkIds: string[], callback: () => Promise<T>): Promise<T> => {\n        lockLinks(shareId, linkIds);\n        try {\n            return await callback();\n        } finally {\n            const volumeId = volumeState.findVolumeId(shareId);\n            if (volumeId) {\n                await events.pollEvents.volumes(volumeId);\n            }\n            unlockLinks(shareId, linkIds);\n        }\n    };\n\n    const moveLink = async (\n        abortSignal: AbortSignal,\n        {\n            shareId,\n            newParentLinkId,\n            linkId,\n            newShareId = shareId,\n            silence = false,\n        }: {\n            shareId: string;\n            newParentLinkId: string;\n            linkId: string;\n            newShareId?: string;\n            silence?: boolean;\n        }\n    ) => {\n        const [\n            link,\n            { passphrase, passphraseSessionKey },\n            newParentPrivateKey,\n            newParentHashKey,\n            { privateKey: addressKey, address },\n        ] = await Promise.all([\n            getLink(abortSignal, shareId, linkId),\n            getLinkPassphraseAndSessionKey(abortSignal, shareId, linkId),\n            getLinkPrivateKey(abortSignal, newShareId, newParentLinkId),\n            getLinkHashKey(abortSignal, newShareId, newParentLinkId),\n            getShareCreatorKeys(abortSignal, newShareId),\n        ]);\n\n        if (link.corruptedLink) {\n            throw new Error('Cannot move corrupted file');\n        }\n\n        const [currentParentPrivateKey, Hash, ContentHash, { NodePassphrase, NodePassphraseSignature }] =\n            await Promise.all([\n                getLinkPrivateKey(abortSignal, shareId, link.parentLinkId),\n                generateLookupHash(link.name, newParentHashKey).catch((e) =>\n                    Promise.reject(\n                        new EnrichedError('Failed to generate lookup hash during move', {\n                            tags: {\n                                shareId,\n                                newParentLinkId,\n                                newShareId: newShareId === shareId ? undefined : newShareId,\n                                linkId,\n                            },\n                            extra: { e },\n                        })\n                    )\n                ),\n                link.digests?.sha1 &&\n                    generateLookupHash(link.digests.sha1, newParentHashKey).catch((e) =>\n                        Promise.reject(\n                            new EnrichedError('Failed to generate content hash during move', {\n                                tags: {\n                                    shareId,\n                                    newParentLinkId,\n                                    newShareId: newShareId === shareId ? undefined : newShareId,\n                                    linkId,\n                                },\n                                extra: { e },\n                            })\n                        )\n                    ),\n                encryptPassphrase(newParentPrivateKey, addressKey, passphrase, passphraseSessionKey).catch((e) =>\n                    Promise.reject(\n                        new EnrichedError('Failed to encrypt link passphrase during move', {\n                            tags: {\n                                shareId,\n                                newParentLinkId,\n                                newShareId: newShareId === shareId ? undefined : newShareId,\n                                linkId,\n                            },\n                            extra: { e },\n                        })\n                    )\n                ),\n            ]);\n\n        const sessionKeyName = await getDecryptedSessionKey({\n            data: link.encryptedName,\n            privateKeys: currentParentPrivateKey,\n        }).catch((e) =>\n            Promise.reject(\n                new EnrichedError('Failed to decrypt link name session key during move', {\n                    tags: {\n                        shareId,\n                        newParentLinkId,\n                        newShareId: newShareId === shareId ? undefined : newShareId,\n                        linkId,\n                    },\n                    extra: { e },\n                })\n            )\n        );\n\n        const { message: encryptedName } = await CryptoProxy.encryptMessage({\n            textData: link.name,\n            stripTrailingSpaces: true,\n            sessionKey: sessionKeyName,\n            encryptionKeys: newParentPrivateKey,\n            signingKeys: addressKey,\n        }).catch((e) =>\n            Promise.reject(\n                new EnrichedError('Failed to encrypt link name during move', {\n                    tags: {\n                        shareId,\n                        newParentLinkId,\n                        newShareId: newShareId === shareId ? undefined : newShareId,\n                        linkId,\n                    },\n                    extra: { e },\n                })\n            )\n        );\n\n        await debouncedRequest({\n            ...queryMoveLink(shareId, linkId, {\n                Name: encryptedName,\n                Hash,\n                ParentLinkID: newParentLinkId,\n                NodePassphrase,\n                NodePassphraseSignature,\n                SignatureAddress: address.Email,\n                NewShareID: newShareId === shareId ? undefined : newShareId,\n                ContentHash,\n            }),\n            silence,\n        }).catch((err) => {\n            if (INVALID_REQUEST_ERROR_CODES.includes(err?.data?.Code)) {\n                throw new ValidationError(err.data.Error);\n            }\n            throw err;\n        });\n\n        const originalParentId = link.parentLinkId;\n        return originalParentId;\n    };\n\n    const moveLinks = async (\n        abortSignal: AbortSignal,\n        {\n            shareId,\n            linkIds,\n            newParentLinkId,\n            newShareId,\n            onMoved,\n            onError,\n            silence,\n        }: {\n            shareId: string;\n            linkIds: string[];\n            newParentLinkId: string;\n            newShareId?: string;\n            onMoved?: (linkId: string) => void;\n            onError?: (linkId: string) => void;\n            silence?: boolean;\n        }\n    ) => {\n        return withLinkLock(shareId, linkIds, async () => {\n            const originalParentIds: { [linkId: string]: string } = {};\n            const successes: string[] = [];\n            const failures: { [linkId: string]: any } = {};\n\n            const moveQueue = linkIds.map((linkId) => async () => {\n                return moveLink(abortSignal, { shareId, newParentLinkId, linkId, newShareId, silence })\n                    .then((originalParentId) => {\n                        successes.push(linkId);\n                        originalParentIds[linkId] = originalParentId;\n                        onMoved?.(linkId);\n                    })\n                    .catch((error) => {\n                        failures[linkId] = error;\n                        onError?.(linkId);\n                    });\n            });\n\n            await preventLeave(runInQueue(moveQueue, MAX_THREADS_PER_REQUEST));\n            return { successes, failures, originalParentIds };\n        });\n    };\n\n    /**\n     * batchHelper makes easier to do any action with many links in several\n     * batches to make sure API can handle it (to not send thousands of links\n     * in one request), all run in parallel (up to a reasonable limit).\n     */\n    const batchHelper = async <T>(\n        abortSignal: AbortSignal,\n        shareId: string,\n        linkIds: string[],\n        query: (batchLinkIds: string[], shareId: string) => any,\n        maxParallelRequests = MAX_THREADS_PER_REQUEST\n    ) => {\n        return withLinkLock(shareId, linkIds, async () => {\n            const responses: { batchLinkIds: string[]; response: T }[] = [];\n            const successes: string[] = [];\n            const failures: { [linkId: string]: any } = {};\n\n            const batches = chunk(linkIds, BATCH_REQUEST_SIZE);\n\n            const queue = batches.map(\n                (batchLinkIds) => () =>\n                    debouncedRequest<T>(query(batchLinkIds, shareId), abortSignal)\n                        .then((response) => {\n                            responses.push({ batchLinkIds, response });\n                            batchLinkIds.forEach((linkId) => successes.push(linkId));\n                        })\n                        .catch((error) => {\n                            batchLinkIds.forEach((linkId) => (failures[linkId] = error));\n                        })\n            );\n            await preventLeave(runInQueue(queue, maxParallelRequests));\n            return {\n                responses,\n                successes,\n                failures,\n            };\n        });\n    };\n\n    const batchHelperMultipleShares = async (\n        abortSignal: AbortSignal,\n        ids: { shareId: string; linkId: string }[],\n        query: (batchLinkIds: string[], shareId: string) => any,\n        maxParallelRequests = MAX_THREADS_PER_REQUEST\n    ) => {\n        const groupedByShareId = groupWith((a, b) => a.shareId === b.shareId, ids);\n\n        const results = await Promise.all(\n            groupedByShareId.map((group) => {\n                return batchHelper<APIResponses>(\n                    abortSignal,\n                    group[0].shareId,\n                    group.map(({ linkId }) => linkId),\n                    query,\n                    maxParallelRequests\n                );\n            })\n        );\n\n        const { responses, failures } = accumulateResults(results);\n        const successes: string[] = [];\n        responses.forEach(({ batchLinkIds, response }) => {\n            response.Responses.forEach(({ Response }, index) => {\n                const linkId = batchLinkIds[index];\n                if (!Response.Error) {\n                    successes.push(linkId);\n                } else if (INVALID_REQUEST_ERROR_CODES.includes(Response.Code)) {\n                    failures[linkId] = new ValidationError(Response.Error);\n                } else {\n                    failures[linkId] = Response.Error;\n                }\n            });\n        });\n        return { responses, successes, failures };\n    };\n\n    const trashLinks = async (\n        abortSignal: AbortSignal,\n        ids: { shareId: string; linkId: string; parentLinkId: string }[]\n    ) => {\n        const linksByParentIds = groupWith((a, b) => a.parentLinkId === b.parentLinkId, ids);\n\n        const results = await Promise.all(\n            linksByParentIds.map((linksGroup) => {\n                const groupParentLinkId = linksGroup[0].parentLinkId;\n\n                return batchHelperMultipleShares(abortSignal, linksGroup, (batchLinkIds, shareId) => {\n                    return queries.queryTrashLinks(shareId, groupParentLinkId, batchLinkIds);\n                });\n            })\n        );\n\n        return accumulateResults(results);\n    };\n\n    const restoreLinks = async (abortSignal: AbortSignal, ids: { shareId: string; linkId: string }[]) => {\n        /*\n            Make sure to restore the most freshly trashed links first to ensure\n            the potential parents are restored first because it is not possible\n            to restore child if the parent stays in the trash.\n            If user does not select the parent anyway, it is fine, it will just\n            show error notification that some link(s) were not restored.\n        */\n        const links = await getLinks(abortSignal, ids);\n        const sortedLinks = links.sort((a, b) => (b.trashed || 0) - (a.trashed || 0));\n        const sortedLinkIds = sortedLinks.map(({ linkId, rootShareId }) => ({ linkId, shareId: rootShareId }));\n\n        // Limit restore to one thread at a time only to make sure links are\n        // restored in proper order (parents need to be restored before childs).\n        const maxParallelRequests = 1;\n\n        const results = await batchHelperMultipleShares(\n            abortSignal,\n            sortedLinkIds,\n            (batchLinkIds, shareId) => {\n                return queries.queryRestoreLinks(shareId, batchLinkIds);\n            },\n            maxParallelRequests\n        );\n\n        return results;\n    };\n\n    const deleteChildrenLinks = async (\n        abortSignal: AbortSignal,\n        shareId: string,\n        parentLinkId: string,\n        linkIds: string[]\n    ) => {\n        return batchHelper(abortSignal, shareId, linkIds, (batchLinkIds) =>\n            queryDeleteChildrenLinks(shareId, parentLinkId, batchLinkIds)\n        );\n    };\n\n    const deleteTrashedLinks = async (abortSignal: AbortSignal, ids: { linkId: string; shareId: string }[]) => {\n        return batchHelperMultipleShares(abortSignal, ids, (batchLinkIds, shareId) => {\n            return queries.queryDeleteTrashedLinks(shareId, batchLinkIds);\n        });\n    };\n\n    const emptyTrash = async (abortSignal: AbortSignal) => {\n        const { volumeId } = await getDefaultShare();\n        lockTrash();\n        await debouncedRequest(queryVolumeEmptyTrash(volumeId), abortSignal);\n\n        await events.pollEvents.volumes(volumeId);\n    };\n\n    return {\n        moveLinks,\n        trashLinks,\n        restoreLinks,\n        deleteChildrenLinks,\n        deleteTrashedLinks,\n        emptyTrash,\n    };\n}\n\nexport default function useLinksActionsWithQuieries() {\n    return useLinksActions({\n        queries: {\n            queryTrashLinks,\n            queryDeleteChildrenLinks,\n            queryDeleteTrashedLinks,\n            queryEmptyTrashOfShare,\n            queryRestoreLinks,\n        },\n    });\n}\n\ninterface Result<T> {\n    responses: {\n        batchLinkIds: string[];\n        response: T;\n    }[];\n    successes: string[];\n    failures: {\n        [linkId: string]: any;\n    };\n}\n\nfunction accumulateResults<T>(results: Result<T>[]): Result<T> {\n    return results.reduce(\n        (acc, result) => {\n            acc.responses.push(...result.responses);\n            acc.successes.push(...result.successes);\n            acc.failures = { ...acc.failures, ...result.failures };\n            return acc;\n        },\n        {\n            responses: [],\n            successes: [],\n            failures: {},\n        }\n    );\n}\n","export const convertSubjectAreaToSubjectCoordinates = (subjectArea: number[]) => {\n    if (subjectArea.length === 2) {\n        // Case: X, Y\n        const [x, y] = subjectArea;\n        return { top: y, left: x, bottom: y, right: x };\n    } else if (subjectArea.length === 3) {\n        // Case: X, Y, Diameter\n        const [x, y, diameter] = subjectArea;\n        const radius = Math.floor(diameter / 2);\n        return { top: y - radius, left: x - radius, bottom: y + radius, right: x + radius };\n    } else if (subjectArea.length === 4) {\n        // Case: X, Y, Width, Length\n        const [x, y, width, height] = subjectArea;\n        const middleHeight = Math.floor(height / 2);\n        const middleWidth = Math.floor(width / 2);\n        return { top: y - middleHeight, left: x - middleWidth, bottom: y + middleHeight, right: x + middleWidth };\n    }\n\n    // Invalid subject area format\n    throw new Error('Invalid exif SubjectArea was passed');\n};\n","export const formatExifDateTime = (exifDateTime: string) => {\n    const regex = /^\\d{4}:\\d{2}:\\d{2} \\d{2}:\\d{2}:\\d{2}$/;\n    if (!regex.test(exifDateTime)) {\n        throw new Error(\n            `The DateTime passed is not in the right format (received: ${exifDateTime}, expected: YYYY:MM:DD HH:MM:SS)`\n        );\n    }\n    const splitDate = exifDateTime.split(' ');\n    //get date part and replace ':' with '-'\n    const dateStr = splitDate[0].replace(/:/g, '-');\n    //concat the strings (date and time part)\n    return dateStr + ' ' + splitDate[1];\n};\n","import { fromUnixTime, isThisMonth, isThisYear } from 'date-fns';\nimport { c } from 'ttag';\n\nimport { getMonthFormatter, getMonthYearFormatter } from '../../../utils/intl/dateFormatter';\nimport type { PhotoGridItem, PhotoGroup, PhotoLink } from '../interface';\n\nconst dateToCategory = (timestamp: number): PhotoGroup => {\n    if (timestamp < 0) {\n        return c('Info').t`Unknown date`;\n    }\n\n    const date = fromUnixTime(timestamp);\n\n    if (isThisMonth(date)) {\n        return c('Info').t`This month`;\n    } else if (isThisYear(date)) {\n        return getMonthFormatter().format(date);\n    }\n\n    return getMonthYearFormatter().format(date);\n};\n\n// For sorting, we will try to obtain captureTime in the following order:\n// captureTime (almost guaranteed to be there) -> createTime (if decrypted) -> negative date fallback\nconst captureTime = (link: PhotoLink) =>\n    link.activeRevision?.photo?.captureTime || ('createTime' in link && link.createTime) || -1;\n\nexport const sortWithCategories = (data: PhotoLink[]): PhotoGridItem[] => {\n    const result: PhotoGridItem[] = [];\n    let lastGroup = '';\n\n    // Latest to oldest\n    data.sort((a, b) => captureTime(b) - captureTime(a));\n    data.forEach((item) => {\n        const group = dateToCategory(captureTime(item));\n\n        if (group !== lastGroup) {\n            lastGroup = group;\n            result.push(group);\n        }\n\n        result.push(item);\n    });\n\n    return result;\n};\n","import ExifReader from 'exifreader';\nimport type { ExifTags, ExpandedTags } from 'exifreader';\n\nimport { CryptoProxy, PrivateKeyReference } from '@proton/crypto';\nimport { encodeBase64 } from '@proton/crypto/lib/utils';\nimport { isSVG } from '@proton/shared/lib/helpers/mimetype';\n\nimport { convertSubjectAreaToSubjectCoordinates, formatExifDateTime } from './utils';\n\nexport const getExifInfo = async (file: File, mimeType: string): Promise<ExpandedTags | undefined> => {\n    if (isSVG(mimeType)) {\n        return undefined;\n    }\n\n    const buffer = await file.arrayBuffer();\n\n    try {\n        // Notes: XMP read is disabled because DOMParser is not available in Worker (package.json > exifreader)\n        return ExifReader.load(buffer, { expanded: true });\n    } catch (err) {}\n\n    return undefined;\n};\n\nexport async function encryptExifInfo(\n    exifInfo: ExpandedTags,\n    nodePrivateKey: PrivateKeyReference,\n    addressPrivateKey: PrivateKeyReference\n) {\n    const exifInfoString = JSON.stringify(exifInfo);\n    const { message } = await CryptoProxy.encryptMessage({\n        textData: exifInfoString,\n        encryptionKeys: nodePrivateKey,\n        signingKeys: addressPrivateKey,\n        compress: true,\n        context: { value: 'drive.photo.exif', critical: true },\n    });\n    return encodeBase64(message);\n}\n\nexport const getFormattedDateTime = (exif?: ExifTags) => {\n    if (!exif) {\n        return undefined;\n    }\n    const sources = [exif.DateTimeOriginal, exif.DateTimeDigitized, exif.DateTime];\n    for (let i = 0; i < sources.length; i++) {\n        const source = sources[i];\n        if (!source?.value[0]) {\n            continue;\n        }\n        try {\n            return formatExifDateTime(source.value[0]);\n        } catch {\n            continue;\n        }\n    }\n    return undefined;\n};\n\nexport const getCaptureDateTime = (file: File, exif?: ExifTags) => {\n    const formattedDateTime = getFormattedDateTime(exif);\n\n    // If file.lastModified is not know, current date will be returned:\n    // https://developer.mozilla.org/en-US/docs/Web/API/File/lastModified\n    const captureDateTime = new Date(formattedDateTime || file.lastModified);\n\n    return captureDateTime;\n};\n\nexport const getPhotoDimensions = ({ exif, png }: ExpandedTags): { width?: number; height?: number } => ({\n    width: exif?.ImageWidth?.value || exif?.PixelXDimension?.value || png?.['Image Width']?.value,\n    height: exif?.ImageLength?.value || exif?.PixelYDimension?.value || png?.['Image Height']?.value,\n});\n\nexport const getCaptureDateTimeString = (exif?: ExifTags) => {\n    const formattedDateTime = getFormattedDateTime(exif);\n    return formattedDateTime ? new Date(formattedDateTime).toISOString() : undefined;\n};\n\nexport const getPhotoExtendedAttributes = ({ exif, gps }: ExpandedTags) => ({\n    location:\n        gps?.Latitude && gps?.Longitude\n            ? {\n                  latitude: gps.Latitude,\n                  longitude: gps.Longitude,\n              }\n            : undefined,\n    camera: exif\n        ? {\n              device: exif.Model?.value[0],\n              orientation: exif.Orientation?.value,\n              captureTime: getCaptureDateTimeString(exif),\n              subjectCoordinates: exif.SubjectArea?.value\n                  ? convertSubjectAreaToSubjectCoordinates(exif.SubjectArea.value)\n                  : undefined,\n          }\n        : undefined,\n});\n","import { updateServerTime as internalUpdateServerTime, serverTime } from 'pmcrypto-v6-canary/lib/serverTime';\n\nlet updateCalled = false;\n/**\n * If `updateServerTime()` is never called, then `serverTime()` returns the device time.\n * This helpers is for debugging purposes and returns whether the serverTime is indeed being used.\n */\nconst wasServerTimeEverUpdated = () => updateCalled;\nconst updateServerTime = (serverDate: Date) => {\n    updateCalled = true;\n    return internalUpdateServerTime(serverDate);\n};\n\nexport { serverTime, updateServerTime, wasServerTimeEverUpdated };\n","/* eslint @typescript-eslint/no-use-before-define: 0 */\n\n/**\n * Returns `true` if the passed parameter is an `Error`.\n */\nexport const isError = (e: unknown): e is Error =>\n    e instanceof Error ||\n    (!!e &&\n        typeof e === 'object' &&\n        'name' in e &&\n        typeof e.name === 'string' &&\n        'message' in e &&\n        typeof e.message === 'string');\n\ntype SafeValue = string | number | boolean | undefined | null | SafeObject | SafeValue[];\ntype SafeObject = { [key: string]: SafeValue };\nexport type SafeErrorObject = {\n    name: string;\n    message: string;\n    stack?: string;\n\n    // Used by Drive errors\n    isEnrichedError?: boolean;\n    context?: SafeObject;\n    sentryMessage?: string;\n};\n\n/**\n * Transforms an arbitrary value into something that is safe to transfer through `postMessage`.\n */\nexport function getSafeValue(value: any): SafeValue {\n    if (\n        typeof value === 'string' ||\n        typeof value === 'number' ||\n        typeof value === 'boolean' ||\n        value === undefined ||\n        value === null\n    ) {\n        return value;\n    }\n\n    if (isError(value)) {\n        return getSafeErrorObject(value);\n    }\n\n    if (Array.isArray(value)) {\n        return getSafeArray(value);\n    }\n\n    if (typeof value === 'object') {\n        return getSafeObject(value);\n    }\n\n    return undefined;\n}\n\n/**\n * Returns an array of objects that is safe to transfer through `postMessage`.\n *\n * Some elements may be transformed into `undefined` if they are not safe.\n */\nexport function getSafeArray(value: any[]): SafeValue[] {\n    return value.map(getSafeValue);\n}\n\n/**\n * Returns an object that is safe to transfer through `postMessage`.\n */\nexport function getSafeObject(obj: any): SafeObject | undefined {\n    if (typeof obj !== 'object') {\n        return undefined;\n    }\n\n    let result: SafeObject = {};\n\n    Object.entries(obj).forEach(([key, value]) => {\n        const safeValue = getSafeValue(value);\n\n        if (safeValue !== undefined) {\n            result[key] = safeValue;\n        }\n    });\n\n    return result;\n}\n\n/**\n * Returns a safe Error-like object that can be transferred through `postMessage`.\n * Mainly needed because Safari <= 16 errors when cloning Error objects.\n */\nexport function getSafeErrorObject(error: Error): SafeErrorObject {\n    return {\n        name: error.name,\n        message: error.message,\n        stack: error.stack,\n\n        // Used by Drive errors to provide additional data to Sentry\n        isEnrichedError: (error as any).isEnrichedError,\n        context: getSafeObject((error as any).context),\n        sentryMessage: (error as any).sentryMessage,\n    };\n}\n","import { c } from 'ttag';\n\nimport { DRIVE_APP_NAME } from '@proton/shared/lib/constants';\n\nexport const isRefreshError = (err: any): err is RefreshError => {\n    return err.name === 'RefreshError';\n};\n\n/**\n * Builds a localized `RefreshError`. Useful to let the user know they should refresh the page.\n *\n * @see RefreshError\n *\n * @example\n *\n * import('./module').catch(() => Promise.reject(getRefreshError()));\n */\nexport const getRefreshError = () =>\n    new RefreshError(c('Error').t`${DRIVE_APP_NAME} has updated. Please refresh the page.`);\n\nconst REFRESH_MESSAGE = 'Please refresh the page.';\n\n/**\n * This error denotes to the user they should refresh their page.\n * This should be chained to `import()`, `new Worker()` or `serviceWorker.register`.\n *\n * You should use `getRefreshError` to build a Refresh Error.\n *\n * If you are in a context where ttag is not available (i.e. worker), you can use this\n * constructor directly and rebuild it on the main thread for localization.\n */\nexport class RefreshError extends Error {\n    sentryMessage: string = REFRESH_MESSAGE;\n\n    constructor(message?: string) {\n        super(message || REFRESH_MESSAGE);\n        this.name = 'RefreshError';\n    }\n}\n","/**\n * How many times failed request is retried before giving up and failing\n * the whole upload.\n */\nexport const MAX_RETRIES_BEFORE_FAIL = 3;\n\n/**\n * MAX_ENCRYPTED_BLOCKS limits the number of blocks in the buffer before\n * asking API for next batch of links, if not asked sooner by low buffer\n * of uploading blocks.\n */\nexport const MAX_ENCRYPTED_BLOCKS = 15;\n\n/**\n * MAX_UPLOADING_BLOCKS limits the number of blocks in the buffer for\n * upload. It should be a bit bigger than MAX_UPLOAD_JOBS to ensure that\n * there is always ready next block when any upload job finishes current\n * upload. When there is not enough uploading jobs, worker asks for link\n * creation sooner than it hits the ideal size of MAX_ENCRYPTED_BLOCKS.\n */\nexport const MAX_UPLOADING_BLOCKS = 10;\n\n/**\n * MAX_BLOCKS_PER_UPLOAD is how many blocks can one upload job have buffered\n * in memory. Used to count the current load for the total limit of ongoing\n * upload files by MAX_UPLOAD_BLOCKS_LOAD.\n */\nexport const MAX_BLOCKS_PER_UPLOAD = MAX_ENCRYPTED_BLOCKS + MAX_UPLOADING_BLOCKS;\n\n/**\n * MAX_UPLOAD_BLOCKS_LOAD limits the number of total blocks being uploaded\n * at one time. If the queue contains only big files, only few of them at\n * a time is allowed to limit the memory requirements. If the queue contains\n * small files, more can be uploaded in parallel. But each upload mean extra\n * worker. Even though browsers support up to hunderds of web workers, still\n * it spawns threads.\n */\nexport const MAX_UPLOAD_BLOCKS_LOAD = 4;\n\n/**\n * MAX_UPLOAD_FOLDER_LOAD limits the number of total folder being created\n * at one time.\n */\nexport const MAX_UPLOAD_FOLDER_LOAD = 5;\n\n/**\n * How many ongoing uploads there can be. Without http2, we cannot do more\n * than six parallel requests to one host. With http2 (which we use), there\n * is theretically no limit, but still we should make a reasonable limit\n * to not kill users device.\n */\nexport const MAX_UPLOAD_JOBS = 5;\n\n/**\n * WAIT_TIME is used for pauses between checks, such as to check if buffer is\n * still full or not, or if the upload is paused, and so on.\n */\nexport const WAIT_TIME = 50; // Milliseconds.\n\n/**\n * TOKEN_EXPIRATION_TIME defines after what time server expires the token.\n * We can optimise and not even ask for block upload if we know the token\n * is already old and we should ask for new one.\n */\nexport const TOKEN_EXPIRATION_TIME = 3 * 60 * 60 * 1000; // Milliseconds.\n\n/**\n * MAX_TOO_MANY_REQUESTS_WAIT defines how many seconds is allowed to wait\n * if server rate limits upload. If server asks to wait longer, we don't\n * wait and fail right away instead.\n */\nexport const MAX_TOO_MANY_REQUESTS_WAIT = 60 * 60; // Seconds.\n\n/**\n * MAX_BLOCK_VERIFICATION_RETRIES defines how many times we will retry\n * encrypting a block if it fails verification.\n *\n * For context, blocks are verified after encryption to check for\n * corrupted encrypted data. If this fails, we retry creating the block\n * entirely. The main utility is to mitigate bitflip issues.\n */\nexport const MAX_BLOCK_VERIFICATION_RETRIES = 1;\n\n/**\n * Amount of time between heartbeats. These are used to ensure the worker\n * is still alive, and not stuck in a bad state.\n */\nexport const HEARTBEAT_INTERVAL = 30 * 1000; // ms\n\n/**\n * Amount of time to wait for a new heartbeat. If no heartbeat is received\n * during this interval, we cancel and restart the worker.\n *\n * This should be greater than HEARTBEAT_INTERVAL;\n */\nexport const HEARTBEAT_WAIT_TIME = HEARTBEAT_INTERVAL * 2; // ms\n\n/**\n * Amout of time to wait for messages after initialization before considering\n * the worker is dead and asking the user to refresh the page.\n *\n * On Chrome, we have no way to know if a worker fetch was successful.\n */\nexport const WORKER_INIT_WAIT_TIME = 5 * 1000; // ms\n","export const wait = (delay: number) => new Promise<void>((resolve) => setTimeout(resolve, delay));\n\n/**\n * Runs each chunk from a chunks array and waits after each one has run (unless it's the last one).\n */\nexport const runChunksDelayed = async <T>(\n    chunks: number[][] = [],\n    cb: (index: number) => Promise<T>,\n    delay: number\n) => {\n    const promises = [];\n\n    for (let i = 0; i < chunks.length; ++i) {\n        promises.push(...chunks[i].map(cb));\n        if (i !== chunks.length - 1) {\n            await wait(delay);\n        }\n    }\n\n    return Promise.all(promises);\n};\n\nexport const createPromise = <T>() => {\n    let resolve!: (value: T | PromiseLike<T>) => void;\n    let reject!: (reason?: any) => void;\n\n    const promise = new Promise<T>((innerResolve, innerReject) => {\n        resolve = innerResolve;\n        reject = innerReject;\n    });\n\n    return { promise, resolve, reject };\n};\n","import { WAIT_TIME } from '../constants';\n\nexport function waitForCondition(callback: () => boolean) {\n    return new Promise<void>((resolve) => {\n        const waitForCondition = () => {\n            if (callback()) {\n                return resolve();\n            }\n            setTimeout(waitForCondition, WAIT_TIME);\n        };\n        waitForCondition();\n    });\n}\n\nexport class Pauser {\n    isPaused = false;\n\n    abortController = new AbortController();\n\n    pause() {\n        this.isPaused = true;\n        this.abortController.abort();\n    }\n\n    resume() {\n        this.abortController = new AbortController();\n        this.isPaused = false;\n    }\n\n    async waitIfPaused() {\n        await waitForCondition(() => !this.isPaused);\n    }\n}\n","export default class ChunkFileReader {\n    private blob: Blob;\n\n    private chunkSize: number;\n\n    private offset = 0;\n\n    constructor(file: Blob, chunkSize: number) {\n        this.blob = file;\n        this.chunkSize = chunkSize;\n    }\n\n    isEOF() {\n        return this.offset >= this.blob.size;\n    }\n\n    async readNextChunk() {\n        const fileReader = new FileReader();\n        const blob = this.blob.slice(this.offset, this.offset + this.chunkSize);\n\n        return new Promise<Uint8Array>((resolve, reject) => {\n            fileReader.onerror = (e) => {\n                reject(e.target?.error || new Error('Cannot open file for reading'));\n            };\n\n            fileReader.onabort = () => {\n                reject(new Error('File read aborted'));\n            };\n\n            fileReader.onload = async (e) => {\n                if (!e.target || !e.target.result || e.target?.error) {\n                    return reject(e.target?.error || new Error('Cannot open file for reading'));\n                }\n\n                const result = new Uint8Array(e.target.result as ArrayBuffer);\n                this.offset += result.byteLength;\n                resolve(result);\n            };\n\n            fileReader.readAsArrayBuffer(blob);\n        });\n    }\n}\n","import type { sha1 } from '@openpgp/noble-hashes/sha1';\n\nimport { CryptoProxy, PrivateKeyReference, SessionKey } from '@proton/crypto';\nimport { FILE_CHUNK_SIZE } from '@proton/shared/lib/drive/constants';\nimport { generateContentHash } from '@proton/shared/lib/keys/driveKeys';\n\nimport { EnrichedError } from '../../../utils/errorHandling/EnrichedError';\nimport ChunkFileReader from '../ChunkFileReader';\nimport { MAX_BLOCK_VERIFICATION_RETRIES } from '../constants';\nimport { EncryptedBlock, ThumbnailEncryptedBlock } from '../interface';\nimport { ThumbnailInfo } from '../media';\nimport { Verifier } from './interface';\n\ntype LogCallback = (message: string) => void;\n\n/**\n * generateEncryptedBlocks generates blocks for the specified file.\n * Each block is chunked to FILE_CHUNK_SIZE and encrypted, counting index\n * from one.\n */\nexport async function* generateEncryptedBlocks(\n    file: File,\n    addressPrivateKey: PrivateKeyReference,\n    privateKey: PrivateKeyReference,\n    sessionKey: SessionKey,\n    postNotifySentry: (e: Error) => void,\n    hashInstance: ReturnType<typeof sha1.create>,\n    verifier: Verifier,\n    log: LogCallback\n): AsyncGenerator<EncryptedBlock> {\n    log(`Encrypting blocks`);\n    let index = 1;\n    const reader = new ChunkFileReader(file, FILE_CHUNK_SIZE);\n    while (!reader.isEOF()) {\n        const chunk = await reader.readNextChunk();\n\n        hashInstance.update(chunk);\n\n        yield await encryptBlock(\n            index++,\n            chunk,\n            addressPrivateKey,\n            privateKey,\n            sessionKey,\n            verifier,\n            postNotifySentry,\n            log\n        );\n    }\n    log(`Encrypting blocks finished`);\n}\n\n/**\n * generateEncryptedThumbnailsBlocks generates blocks for the specified thumbnails\n * Each thumbnail will fit on a single block.\n * Index is not taken in consideration for Thumbnails, so we can start it at 0\n */\nexport async function* generateThumbnailEncryptedBlocks(\n    thumbnails: ThumbnailInfo[] | undefined,\n    addressPrivateKey: PrivateKeyReference,\n    sessionKey: SessionKey,\n    log: LogCallback\n): AsyncGenerator<ThumbnailEncryptedBlock> {\n    if (!thumbnails?.length) {\n        log(`No thumbnail to encrypt`);\n        return;\n    }\n\n    log(`Encrypting ${thumbnails.length} thumbnails`);\n    let index = 0;\n    for (let i = 0; i < thumbnails.length; i++) {\n        yield await encryptThumbnail(index++, addressPrivateKey, sessionKey, thumbnails[i]);\n    }\n    log(`Encrypting thumbnails finished`);\n}\n\nasync function encryptThumbnail(\n    index: number,\n    addressPrivateKey: PrivateKeyReference,\n    sessionKey: SessionKey,\n    thumbnail: ThumbnailInfo\n): Promise<ThumbnailEncryptedBlock> {\n    const { message: encryptedData } = await CryptoProxy.encryptMessage({\n        binaryData: thumbnail.thumbnailData,\n        sessionKey,\n        signingKeys: addressPrivateKey,\n        format: 'binary',\n        detached: false,\n    });\n    const hash = (await generateContentHash(encryptedData)).BlockHash;\n    return {\n        index,\n        // Original size is used only for showing progress. We don't want to\n        // include thumbnail to it, otherwise it would show more than 100%.\n        originalSize: 0,\n        encryptedData,\n        hash,\n        thumbnailType: thumbnail.thumbnailType,\n    };\n}\n\nasync function encryptBlock(\n    index: number,\n    chunk: Uint8Array,\n    addressPrivateKey: PrivateKeyReference,\n    privateKey: PrivateKeyReference,\n    sessionKey: SessionKey,\n    verifyBlock: Verifier,\n    postNotifySentry: (e: Error) => void,\n    log: LogCallback\n): Promise<EncryptedBlock> {\n    const tryEncrypt = async (retryCount: number): Promise<EncryptedBlock> => {\n        log(`Encrypting block ${index}`);\n        // Generate the encrypted block\n        const { message: encryptedData, signature } = await CryptoProxy.encryptMessage({\n            binaryData: chunk,\n            sessionKey,\n            signingKeys: addressPrivateKey,\n            format: 'binary',\n            detached: true,\n        });\n\n        // IMPORTANT!\n        // Hashing must happen BEFORE verifying.\n        // If verification is successful, then we know the hash corresponds\n        // to something we can decrypt. If hashing was placed after verification,\n        // the cyphertext could get corrupted after verification succeeds,\n        // which would create an incorrect digest that would look \"correct\" to the server.\n        const hash = (await generateContentHash(encryptedData)).BlockHash;\n        let verificationToken;\n\n        try {\n            verificationToken = await verifyBlock(encryptedData);\n        } catch (e) {\n            // Only trace the error to sentry once\n            if (retryCount === 0) {\n                postNotifySentry(new EnrichedError('Verification failed and retried', { extra: { e } }));\n            }\n\n            if (retryCount < MAX_BLOCK_VERIFICATION_RETRIES) {\n                log(`Block verification failed, retrying: ${e}`);\n                return tryEncrypt(retryCount + 1);\n            }\n\n            log(`Block verification failed: ${e}`);\n            // Give up after max retries reached, something's wrong\n            throw new EnrichedError('Upload failed: Verification of data failed', { extra: { e } });\n        }\n\n        // Encrypt the block signature after verification\n        const { message: encryptedSignature } = await CryptoProxy.encryptMessage({\n            binaryData: signature,\n            sessionKey,\n            encryptionKeys: privateKey,\n        });\n\n        return {\n            index,\n            originalSize: chunk.length,\n            encryptedData,\n            hash,\n            signature: encryptedSignature,\n            verificationToken,\n        };\n    };\n\n    return tryEncrypt(0);\n}\n","import { RETRY_DELAY_MAX } from '@proton/shared/lib/constants';\nimport { ApiError } from '@proton/shared/lib/fetch/ApiError';\nimport { wait } from '@proton/shared/lib/helpers/promise';\n\nexport const retryHandler = (e: ApiError, maxDelay = RETRY_DELAY_MAX) => {\n    const headers = e?.response?.headers;\n\n    const retryAfterSeconds = parseInt(headers?.get('retry-after') || '0', 10);\n\n    if (retryAfterSeconds < 0 || retryAfterSeconds >= maxDelay) {\n        return Promise.reject(e);\n    }\n\n    return wait(retryAfterSeconds * 1000);\n};\n","import UAParser from 'ua-parser-js';\n\nimport { SUPPORTED_ELECTRON_APP } from '@proton/components/hooks/useIsElectronApp';\n\nimport { APPS, APP_NAMES } from '../constants';\nimport { isLinux, isMac, isWindows } from './browser';\n\nconst uaParser = new UAParser();\nconst ua = uaParser.getResult();\n\nexport const isElectronApp = /electron/i.test(ua.ua);\nexport const isElectronOnMac = isElectronApp && isMac();\nexport const isElectronOnWindows = isElectronApp && isWindows();\nexport const isElectronOnLinux = isElectronApp && isLinux();\n\nexport const isElectronOnSupportedApps = (app: APP_NAMES) => {\n    return isElectronApp && SUPPORTED_ELECTRON_APP.includes(app);\n};\n\nexport const isElectronOnInboxApps = (app: APP_NAMES) => {\n    return isElectronApp && (app === APPS.PROTONCALENDAR || app === APPS.PROTONMAIL || app === APPS.PROTONACCOUNT);\n};\n\n/* Electron apps built with Electron Forge will inject the `productName` and\n * `version` properties of the app's package.json in the user-agent. */\nexport const isElectronMail = isElectronApp && /ProtonMail/i.test(ua.ua);\nexport const isElectronPass = isElectr