main functionality of the worker. When keys are generated\n * and file revision created, it passes all information to the worker to\n * do the upload job.\n * First it starts generator for encrypted blocks and pass it to buffer, so\n * it can be buffered and links on API requested. Once the main thread sends\n * back to worker created links, it can pass those blocks to upload jobs.\n * Once the upload jobs finishes, the final result is commited on API.\n * See UploadWorkerBuffer for more details.\n */\nasync function start(\n    file: File,\n    {\n        mimeType,\n        isForPhotos,\n        media,\n        thumbnails,\n    }: {\n        mimeType: string;\n        isForPhotos: boolean;\n        media?: Media;\n        thumbnails?: ThumbnailInfo[];\n    },\n    addressPrivateKey: PrivateKeyReference,\n    addressEmail: string,\n    privateKey: PrivateKeyReference,\n    sessionKey: SessionKey,\n    parentHashKey: Uint8Array,\n    verificationData: VerificationData\n) {\n    const log = (message: string) => uploadWorker.postLog(message);\n    log(`Uploading started`);\n\n    const hashInstance = sha1.create();\n    const verifier = createVerifier(verificationData);\n\n    buffer\n        .feedEncryptedBlocks(\n            generateEncryptedBlocks(\n                file,\n                addressPrivateKey,\n                privateKey,\n                sessionKey,\n                (e) => uploadWorker.postNotifySentry(e),\n                hashInstance,\n                verifier,\n                log\n            ),\n            thumbnails && generateThumbnailEncryptedBlocks(thumbnails, addressPrivateKey, sessionKey, log)\n        )\n        .catch((err) => uploadWorker.postError(err));\n\n    buffer.runBlockLinksCreation((blocks: EncryptedBlock[], thumbnailBlocks?: ThumbnailEncryptedBlock[]) => {\n        uploadWorker.postCreateBlocks(blocks, thumbnailBlocks);\n    });\n\n    const uploadingBlocksGenerator = buffer.generateUploadingBlocks();\n    const finish = async () => {\n        uploadWorker.postLog(`Computing and validating manifest`);\n\n        const fileHash = buffer.hash;\n        const sha1Digest = hashInstance.digest();\n\n        // It seems very unlikely but we had one case when we requested block\n        // upload, provided correct original size, but no block was uploaded\n        // and no hash was present (at least if it was present, backend would\n        // fail the manifest validation).\n        const expectedBlockCount = Math.ceil(file.size / FILE_CHUNK_SIZE) + (thumbnails ? thumbnails?.length : 0);\n        if (buffer.uploadedBlockCount !== expectedBlockCount) {\n            throw new Error('Some file parts failed to upload');\n        }\n        if (buffer.totalProcessedSize !== file.size) {\n            throw new Error('Some file bytes failed to upload');\n        }\n\n        const [signature, exifInfo] = await Promise.all([\n            signMessage(fileHash, [addressPrivateKey]),\n            isForPhotos ? getExifInfo(file, mimeType) : undefined,\n        ]);\n        const photoDimensions = exifInfo ? getPhotoDimensions(exifInfo) : {};\n\n        const { width, height, duration } = {\n            width: media?.width || photoDimensions.width,\n            height: media?.height || photoDimensions.height,\n            duration: media?.duration,\n        };\n\n        const sha1 = arrayToHexString(sha1Digest);\n\n        const [xattr] = await Promise.all([\n            encryptFileExtendedAttributes(\n                {\n                    file,\n                    media:\n                        width && height\n                            ? {\n                                  width,\n                                  height,\n                                  duration,\n                              }\n                            : undefined,\n                    digests: { sha1 },\n                    ...(exifInfo ? getPhotoExtendedAttributes(exifInfo) : {}),\n                },\n                privateKey,\n                addressPrivateKey\n            ),\n        ]);\n\n        uploadWorker.postDone(\n            signature,\n            addressEmail,\n            xattr,\n            isForPhotos\n                ? {\n                      captureTime: getUnixTime(getCaptureDateTime(file, exifInfo?.exif)),\n                      contentHash: sha1 ? await generateLookupHash(sha1, parentHashKey) : undefined,\n                  }\n                : undefined\n        );\n    };\n    startUploadJobs(\n        pauser,\n        uploadingBlocksGenerator,\n        (progress: number) => uploadWorker.postProgress(progress),\n        (error: Error) => uploadWorker.postNetworkError(error),\n        log\n    )\n        .then(finish)\n        .catch((err) => uploadWorker.postError(err));\n}\n\n/**\n * createdBlocks is called as a result to postCreateBlocks.\n */\nfunction createdBlocks(fileLinks: Link[], thumbnailLinks?: Link[]) {\n    buffer.setAllBlockLinks({ fileLinks, thumbnailLinks });\n}\n\nfunction pause() {\n    pauser.pause();\n}\n\nfunction resume() {\n    pauser.resume();\n}\n","import { CryptoProxy, PrivateKeyReference, SessionKey, serverTime, updateServerTime } from '@proton/crypto';\nimport { SafeErrorObject, getSafeErrorObject } from '@proton/utils/getSafeErrorObject';\n\nimport { convertSafeError } from '../../utils/errorHandling/EnrichedError';\nimport { RefreshError, getRefreshError } from '../../utils/errorHandling/RefreshError';\nimport { HEARTBEAT_INTERVAL, HEARTBEAT_WAIT_TIME, WORKER_INIT_WAIT_TIME } from './constants';\nimport type {\n    EncryptedBlock,\n    FileKeys,\n    FileRequestBlock,\n    Link,\n    PhotoUpload,\n    ThumbnailEncryptedBlock,\n    ThumbnailRequestBlock,\n    VerificationData,\n} from './interface';\nimport type { Media, ThumbnailInfo } from './media';\n\ntype GenerateKeysMessage = {\n    command: 'generate_keys';\n    addressPrivateKey: Uint8Array;\n    parentPrivateKey: Uint8Array;\n    serverTime: Date;\n};\n\ntype StartMessage = {\n    command: 'start';\n    file: File;\n    mimeType: string;\n    isForPhotos: boolean;\n    thumbnails?: ThumbnailInfo[];\n    media?: Media;\n    addressPrivateKey: Uint8Array;\n    addressEmail: string;\n    privateKey: Uint8Array;\n    sessionKey: SessionKey;\n    parentHashKey: Uint8Array;\n    verificationData: VerificationData;\n};\n\ntype CreatedBlocksMessage = {\n    command: 'created_blocks';\n    fileLinks: Link[];\n    thumbnailLinks?: Link[];\n};\n\ntype PauseMessage = {\n    command: 'pause';\n};\n\ntype ResumeMessage = {\n    command: 'resume';\n};\n\ntype CloseMessage = {\n    command: 'close';\n};\n\n/**\n * WorkerControllerEvent contains all possible events which can come from\n * the main thread to the upload web worker.\n */\ntype WorkerControllerEvent = {\n    data: GenerateKeysMessage | StartMessage | CreatedBlocksMessage | PauseMessage | ResumeMessage | CloseMessage;\n};\n\n/**\n * WorkerHandlers defines what handlers are available to be used in the upload\n * web worker to messages from the main thread defined in WorkerControllerEvent.\n */\ninterface WorkerHandlers {\n    generateKeys: (addressPrivateKey: PrivateKeyReference, parentPrivateKey: PrivateKeyReference) => void;\n    start: (\n        file: File,\n        {\n            mimeType,\n            isForPhotos,\n            media,\n            thumbnails,\n        }: {\n            mimeType: string;\n            isForPhotos: boolean;\n            thumbnails?: ThumbnailInfo[];\n            media?: Media;\n        },\n        addressPrivateKey: PrivateKeyReference,\n        addressEmail: string,\n        privateKey: PrivateKeyReference,\n        sessionKey: SessionKey,\n        parentHashKey: Uint8Array,\n        verificationData: VerificationData\n    ) => void;\n    createdBlocks: (fileLinks: Link[], thumbnailLinks?: Link[]) => void;\n    pause: () => void;\n    resume: () => void;\n}\n\ntype KeysGeneratedMessage = {\n    command: 'keys_generated';\n    nodeKey: string;\n    nodePassphrase: string;\n    nodePassphraseSignature: string;\n    contentKeyPacket: string;\n    contentKeyPacketSignature: string;\n    privateKey: Uint8Array;\n    sessionKey: SessionKey;\n};\n\ntype CreateBlockMessage = {\n    command: 'create_blocks';\n    fileBlocks: FileRequestBlock[];\n    thumbnailBlocks?: ThumbnailRequestBlock[];\n};\n\ntype ProgressMessage = {\n    command: 'progress';\n    increment: number;\n};\n\ntype DoneMessage = {\n    command: 'done';\n    signature: string;\n    signatureAddress: string;\n    xattr: string;\n    photo?: PhotoUpload;\n};\n\ntype NetworkErrorMessage = {\n    command: 'network_error';\n    error: SafeErrorObject;\n};\n\ntype ErrorMessage = {\n    command: 'error';\n    error: SafeErrorObject;\n};\n\ntype NotifySentryMessage = {\n    command: 'notify_sentry';\n    error: SafeErrorObject;\n};\n\ntype HeartbeatMessage = {\n    command: 'heartbeat';\n};\n\ntype WorkerAliveMessage = {\n    command: 'alive';\n};\n\ntype LogMessage = {\n    command: 'log';\n    message: string;\n};\n\n/**\n * WorkerEvent contains all possible events which can come from the upload\n * web worker to the main thread.\n */\ntype WorkerEvent = {\n    data:\n        | KeysGeneratedMessage\n        | CreateBlockMessage\n        | ProgressMessage\n        | DoneMessage\n        | NetworkErrorMessage\n        | ErrorMessage\n        | NotifySentryMessage\n        | HeartbeatMessage\n        | WorkerAliveMessage\n        | LogMessage;\n};\n\n/**\n * WorkerControllerHandlers defines what handlers are available to be used\n * in the main thread to messages from the upload web worked defined in\n * WorkerEvent.\n */\ninterface WorkerControllerHandlers {\n    keysGenerated: (keys: FileKeys) => void;\n    createBlocks: (fileBlocks: FileRequestBlock[], thumbnailBlocks?: ThumbnailRequestBlock[]) => void;\n    onProgress: (increment: number) => void;\n    finalize: (signature: string, signatureAddress: string, xattr: string, photo?: PhotoUpload) => void;\n    onNetworkError: (error: Error) => void;\n    onError: (error: Error) => void;\n    onHeartbeatTimeout: () => void;\n    onCancel: () => void;\n    notifySentry: (error: Error) => void;\n}\n\n/**\n * UploadWorker provides communication between the main thread and upload web\n * worker. The class ensures type safety as much as possible.\n * UploadWorker is meant to be used on the side of the web worker.\n */\nexport class UploadWorker {\n    worker: Worker;\n\n    heartbeatInterval?: NodeJS.Timeout;\n\n    constructor(worker: Worker, { generateKeys, start, createdBlocks, pause, resume }: WorkerHandlers) {\n        // Before the worker termination, we want to release securely crypto\n        // proxy. That might need a bit of time, and we allow up to few seconds\n        // before we terminate the worker. During the releasing time, crypto\n        // might be failing, so any error should be ignored.\n        let closing = false;\n\n        this.worker = worker;\n\n        // Notify the main thread we are alive.\n        // We use this message to check for failures to load the worker.\n        this.postWorkerAlive();\n\n        // Set up the heartbeat. This notifies the main thread that the worker is still alive.\n        this.heartbeatInterval = setInterval(() => this.postHeartbeat(), HEARTBEAT_INTERVAL);\n\n        worker.addEventListener('message', ({ data }: WorkerControllerEvent) => {\n            switch (data.command) {\n                case 'generate_keys':\n                    (async (data) => {\n                        let module;\n                        // Dynamic import is needed since we want pmcrypto (incl. openpgpjs) to be loaded\n                        // inside the worker, not in the main thread.\n                        try {\n                            module = await import(\n                                /* webpackChunkName: \"crypto-worker-api\" */ '@proton/crypto/lib/worker/api'\n                            );\n                        } catch (e