asically, some browsers (Firefox) seem to handle\n            // failure to load the worker URL in this way, so this is why we have this condition.\n            // https://developer.mozilla.org/en-US/docs/Web/API/ErrorEvent\n            if (!('filename' in event)) {\n                onError(getRefreshError());\n                return;\n            }\n\n            onError(event.error || new Error(event.message));\n        });\n    }\n\n    clearHeartbeatTimeout() {\n        if (this.heartbeatTimeout) {\n            clearTimeout(this.heartbeatTimeout);\n        }\n    }\n\n    terminate() {\n        this.clearHeartbeatTimeout();\n        this.worker.terminate();\n    }\n\n    cancel() {\n        this.onCancel();\n    }\n\n    async postGenerateKeys(addressPrivateKey: PrivateKeyReference, parentPrivateKey: PrivateKeyReference) {\n        this.worker.postMessage({\n            command: 'generate_keys',\n            addressPrivateKey: await CryptoProxy.exportPrivateKey({\n                privateKey: addressPrivateKey,\n                passphrase: null,\n                format: 'binary',\n            }),\n            parentPrivateKey: await CryptoProxy.exportPrivateKey({\n                privateKey: parentPrivateKey,\n                passphrase: null,\n                format: 'binary',\n            }),\n            serverTime: serverTime(),\n        } satisfies GenerateKeysMessage);\n    }\n\n    async postStart(\n        file: File,\n        {\n            mimeType,\n            isForPhotos,\n            thumbnails,\n            media,\n        }: {\n            mimeType: string;\n            isForPhotos: boolean;\n            thumbnails?: ThumbnailInfo[];\n            media?: Media;\n        },\n        addressPrivateKey: PrivateKeyReference,\n        addressEmail: string,\n        privateKey: PrivateKeyReference,\n        sessionKey: SessionKey,\n        parentHashKey: Uint8Array,\n        verificationData: VerificationData\n    ) {\n        this.worker.postMessage({\n            command: 'start',\n            file,\n            mimeType,\n            isForPhotos: isForPhotos,\n            thumbnails,\n            media,\n            addressPrivateKey: await CryptoProxy.exportPrivateKey({\n                privateKey: addressPrivateKey,\n                passphrase: null,\n                format: 'binary',\n            }),\n            addressEmail,\n            privateKey: await CryptoProxy.exportPrivateKey({\n                privateKey: privateKey,\n                passphrase: null,\n                format: 'binary',\n            }),\n            sessionKey,\n            parentHashKey,\n            verificationData,\n        } satisfies StartMessage);\n    }\n\n    postCreatedBlocks(fileLinks: Link[], thumbnailLinks?: Link[]) {\n        this.worker.postMessage({\n            command: 'created_blocks',\n            fileLinks,\n            thumbnailLinks,\n        } satisfies CreatedBlocksMessage);\n    }\n\n    postPause() {\n        this.worker.postMessage({\n            command: 'pause',\n        } satisfies PauseMessage);\n    }\n\n    postResume() {\n        this.worker.postMessage({\n            command: 'resume',\n        } satisfies ResumeMessage);\n    }\n\n    postClose() {\n        this.worker.postMessage({\n            command: 'close',\n        } satisfies CloseMessage);\n    }\n}\n","import { CryptoProxy } from '@proton/crypto';\n\nimport { VerificationData } from '../interface';\nimport { Verifier } from './interface';\n\nexport const createVerifier = ({ verificationCode, verifierSessionKey }: VerificationData): Verifier => {\n    return async (encryptedData: Uint8Array) => {\n        // Attempt to decrypt data block, to try to detect bitflips / bad hardware\n        //\n        // We don't check the signature as it is an expensive operation,\n        // and we don't need to here as we always have the manifest signature\n        //\n        // Additionally, we use the key provided by the verification endpoint, to\n 